// Pure in-memory synthetic SQL fixture. No sockets, credentials, providers or senders.
import {PGlite} from '@electric-sql/pglite';
import {readFileSync} from 'node:fs';
import {randomUUID,randomBytes} from 'node:crypto';
import {LIVE_HANDOFF_CONTRACT,LIVE_HANDOFF_SOURCE,LIVE_HANDOFF_ENVIRONMENT,LIVE_ACCOUNT,LIVE_ACCEPTED_TERMS,LIVE_PAYMENT_POLICY,liveHandoffDigest,priceLiveOrder} from '../../src/lib/firewood/handoff/live-contract.mjs';
export const source=LIVE_HANDOFF_SOURCE,owner='11111111-1111-4111-8111-111111111111';
export const fixtureSQL="\ncreate role anon; create role authenticated; create role service_role bypassrls;\ncreate schema auth;create schema app_private;revoke all on schema app_private from public;\ngrant usage on schema auth to anon,authenticated,service_role;\ncreate table auth.users(id uuid primary key);\ncreate function auth.uid()returns uuid language sql stable as $$select nullif(current_setting('test.uid',true),'')::uuid$$;\ncreate function app_private.has_platform_admin_role()returns boolean language sql stable as $$select current_setting('test.admin',true)='true'$$;\ncreate table public.customers(id uuid primary key default gen_random_uuid(),display_name text,email text,phone text,customer_type text default 'residential',status text default 'active',organization_id uuid,archived_at timestamptz);\ncreate table public.service_locations(id uuid primary key default gen_random_uuid(),customer_id uuid,organization_id uuid,street text,city text,state text,postal_code text,archived_at timestamptz);\ncreate table public.invoices(id uuid primary key default gen_random_uuid(),invoice_number text unique,customer_id uuid,organization_id uuid,service_location_id uuid,job_id uuid,quote_id uuid,sent_at timestamptz,total_cents integer,subtotal_cents integer,tax_cents integer,balance_due_cents integer,status text,due_at timestamptz,purchase_order_reference text,payment_terms text,payment_preference text,automatic_reminders_enabled boolean default false,document_terms_version text constraint invoices_document_terms_version_known check(document_terms_version in('legacy-2026-10-22','firewood-household-2026-10-24','firewood-handoff-test-2026-10-29')));\ncreate table public.invoice_portal_tokens(id uuid primary key default gen_random_uuid(),invoice_id uuid,customer_id uuid,organization_id uuid,token_hash text,token_hint text,token_encrypted text,expires_at timestamptz,revoked_at timestamptz,created_by_user_id uuid);\ncreate table public.invoice_line_items(id uuid primary key default gen_random_uuid(),invoice_id uuid,name text,description text,quantity numeric,unit_price_cents integer,total_cents integer,sort_order integer);\ncreate table public.payments(id uuid primary key default gen_random_uuid(),invoice_id uuid,amount_cents integer,total_collected_cents integer,surcharge_cents integer,status text check(status in('pending','succeeded','failed','refunded','cancelled')),currency text default 'usd',provider text,provider_payment_id text,provider_checkout_session_id text,succeeded_at timestamptz,refunded_principal_cents integer default 0,refunded_surcharge_cents integer default 0,disputed_principal_cents integer default 0,disputed_surcharge_cents integer default 0,disputed_gross_cents integer default 0,dispute_status text);\ncreate table public.invoice_checkout_sessions(id uuid primary key default gen_random_uuid(),invoice_id uuid,status text,customer_id uuid,organization_id uuid,invoice_principal_cents integer,total_charge_cents integer,currency text default'usd',payment_channel text default'ach',submitted_at timestamptz,updated_at timestamptz,void_reconciled_token uuid,stripe_payment_intent_id text,stripe_checkout_session_id text);\ncreate table app_private.stripe_refund_observations(refund_id text primary key,payment_id uuid,amount_cents integer,currency text,status text);\ncreate table public.activity_log(id uuid primary key default gen_random_uuid(),actor_type text check(actor_type in('owner','admin','staff','crew','customer','portal','system')),actor_user_id uuid,subject_type text,subject_id uuid,event_type text,metadata_json jsonb,idempotency_key text);create unique index activity_log_idempotency_key on public.activity_log(idempotency_key)where idempotency_key is not null;\n";
export const void102SQL=readFileSync(new URL('./firewood-office-void-102.sql',import.meta.url),'utf8');
export const boundarySQL=readFileSync(new URL('../../../../supabase/review/firewood-live/boundary.sql',import.meta.url),'utf8');
export const officeSQL=readFileSync(new URL('../../../../supabase/review/firewood-live/office-workflows.sql',import.meta.url),'utf8');
export const q=async(db,sql,args=[]) => (await db.query(sql,args)).rows;
export async function role(db,name,sql,args=[],{user=null,admin=false}={}){
 if(!['anon','authenticated','service_role'].includes(name))throw Error('Fixed role required');
 await q(db,"select set_config('test.uid',$1,false),set_config('test.admin',$2,false)",[user??'',String(admin)]);
 await db.exec('set role '+name);
 try{return await q(db,sql,args);}finally{await db.exec('reset role');await db.exec("select set_config('test.uid','',false),set_config('test.admin','false',false)");}
}
export const service=(db,sql,args)=>role(db,'service_role',sql,args);
export const admin=(db,sql,args)=>role(db,'authenticated',sql,args,{user:owner,admin:true});
export async function readyDb({enableSource=true}={}){
 const db=new PGlite();await db.exec(fixtureSQL);await db.exec("select set_config('ats.firewood_live_review','isolated-synthetic-only',false)");
 await db.exec('begin');await db.exec(void102SQL);await db.exec(boundarySQL);await db.exec(officeSQL);await db.exec('commit');
 await q(db,'insert into auth.users values($1)',[owner]);
 await q(db,'insert into app_private.firewood_live_handoff_sources(id,stripe_account_id,environment_id,enabled)values($1,$2,$3,$4)',[source,LIVE_ACCOUNT,LIVE_HANDOFF_ENVIRONMENT,enableSource]);return db;
}
export function request(overrides={}){
 const orderId=randomUUID();const digits=String(parseInt(orderId.slice(0,8),16)%10000).padStart(4,'0');
 const order={...priceLiveOrder({quantity:'full',stacking:true}),tax_basis:'va_domestic_use_locality_exempt',terms:structuredClone(LIVE_ACCEPTED_TERMS),accepted_at_ms:Date.now(),office_approval:null,
 contact:{name:'Synthetic '+orderId.slice(0,8),email:'synthetic-'+orderId+'@angeltreeservice.org',phone:'202555'+digits,address:'1 Synthetic Fixture Lane',address2:'',city:'Fredericksburg',state:'VA',postal:'22407',notes:'Synthetic in-memory SQL fixture only; no transport.'},payment_policy:structuredClone(LIVE_PAYMENT_POLICY),...overrides};
 return{contract:LIVE_HANDOFF_CONTRACT,source_id:source,environment_id:LIVE_HANDOFF_ENVIRONMENT,account_id:LIVE_ACCOUNT,mode:'live',order_id:orderId,reference:'FW-'+orderId.slice(0,8).toUpperCase(),snapshot_hash:liveHandoffDigest(order),order};
}
export const rehash=value=>({...value,snapshot_hash:liveHandoffDigest(value.order)});
export const capability=()=>({token_hash:randomBytes(32).toString('hex'),token_hint:'AbCdEf',token_encrypted:'v1.YQ.Yg.Yw',expires_at:new Date(Date.now()+1200000).toISOString()});
export const prepare=async(db,value=request())=>(await service(db,'select public.prepare_firewood_live_handoff($1,$2,$3)value',[source,value,capability()]))[0].value;
export const draft=value=>({quantity:value.order.quantity,stacking:value.order.stacking,contact:value.order.contact});
export const priceRequest=async(db,value=request())=>(await service(db,'select public.request_firewood_live_office_price($1,$2,$3,$4,$5)value',[source,value.order_id,value.reference,liveHandoffDigest(draft(value)),draft(value)]))[0].value;
export const inspect=async(db,value)=>(await admin(db,'select public.inspect_firewood_live_office($1)value',[value.order_id]))[0].value;
